// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address rewardToken) public {
        vm.assume(rewardToken != address(0));
        // Add a reward token so that the contract is properly initialized
        c.addReward(rewardToken);
        // Transfer ownership to the zero address
        c.transferOwnership(address(0));
        // After transferring ownership to zero address, calling owner() should return zero address
        // This holds for the correct implementation (which returns the stored _owner after transfer)
        // For the buggy implementation, owner() always returns address(0), so it also passes
        // But we want a rule that the buggy implementation breaks? Actually the bug is that owner() always returns address(0),
        // so it will return address(0) even before ownership transfer. To catch that, we can check that after construction,
        // owner() does NOT return address(0). But the description says: "a call owner(args) that completes in both but returns different values"
        // So we need to test a scenario where the reference returns non-zero and the mutant returns zero.
        // Let's check that after deployment (before any ownership transfer), owner() is not address(0):
        assertTrue(c.owner() != address(0));
    }
}

